// Precompute floor(log2(x)) for every x from 1 to n
vector<int> logTable(int n) {
    vector<int> lg(n + 1);
    lg[1] = 0;
    for (int i = 2; i <= n; i++)
        lg[i] = lg[i / 2] + 1;
    return lg;
}

// Or, without a table, using a compiler builtin:
int fastLog2(int x) {
    return std::__lg(x);   // floor(log2(x)) in O(1)
}

class SparseTable {
    vector<vector<int>> sparse;
    vector<int> lg;
    int n;

public:
    SparseTable(const vector<int>& arr) {
        n = arr.size();
        int K = std::__lg(n) + 1;      // number of levels needed

        lg.assign(n + 1, 0);
        for (int i = 2; i <= n; i++)
            lg[i] = lg[i / 2] + 1;

        sparse.assign(K, vector<int>(n));
        for (int i = 0; i < n; i++)
            sparse[0][i] = arr[i];     // base case, length 1

        for (int k = 1; k < K; k++) {
            int len = 1 << k;
            for (int i = 0; i + len <= n; i++) {
                sparse[k][i] = min(
                    sparse[k - 1][i],
                    sparse[k - 1][i + (1 << (k - 1))]
                );
            }
        }
    }
    // query() defined next
};

int query(int l, int r) {          // inclusive range [l, r], 0-indexed
    int len = r - l + 1;
    int k = lg[len];               // largest power of two that fits

    return min(
        sparse[k][l],
        sparse[k][r - (1 << k) + 1]
    );
}

sparse[k][i] = __gcd(sparse[k - 1][i], sparse[k - 1][i + (1 << (k - 1))]);

int queryGcd(int l, int r) {
    int len = r - l + 1;
    int k = lg[len];
    return __gcd(sparse[k][l], sparse[k][r - (1 << k) + 1]);
}
